def hex_key(num):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    def hex_to_decimal(hex_num):
        decimal_num = 0
        for digit in hex_num:
            if digit.isdigit():
                decimal_num = 16 * decimal_num + int(digit)
            else:
                decimal_num = 16 * decimal_num + ord(digit.upper()) - ord('A') + 10
        return decimal_num

    def count_prime_digits(decimal_num):
        count = 0
        while decimal_num > 0:
            digit = decimal_num % 16
            if is_prime(digit):
                count += 1
            decimal_num //= 16
        return count

    decimal_num = hex_to_decimal(num)
    return count_prime_digits(decimal_num)

