def get_row(lst, x):
    coordinates = []

    for row_idx, row in enumerate(lst):
        if x in row:
            for col_idx, val in enumerate(row):
                if val == x:
                    coordinates.append((row_idx, col_idx))

    coordinates.sort(key=lambda x: x[0])  # Sort by rows in ascending order

    for i in range(len(coordinates)):
        coordinates[i] = (coordinates[i][0], coordinates[i][1]*-1)  # Sort columns in descending order

    return coordinates

