from typing import List

def sort_numbers(numbers: str) -> str:
    numeral_dict = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    def convert_to_numeral(numeral: str) -> int:
        return numeral_dict[numeral]

    def convert_to_numeral_str(numeral: int) -> str:
        return list(numeral_dict.keys())[list(numeral_dict.values()).index(numeral)]

    extracted_numbers = numbers.split()
    mapped_numbers = [convert_to_numeral(num) for num in extracted_numbers]
    sorted_numbers = sorted(mapped_numbers)
    sorted_numeral_values = [convert_to_numeral_str(num) for num in sorted_numbers]
    sorted_string = ' '.join(sorted_numeral_values)

    return sorted_string
