from typing import List

def sort_numbers(numbers: str) -> str:
    # Parse the input string to extract individual numbers
    num_dict = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    num_list = numbers.split()

    # Convert textual numbers to numerical values
    num_values = [num_dict[num] for num in num_list]

    # Sort the numerical values in ascending order
    sorted_nums = sorted(num_values)

    # Convert the sorted numerical values back to textual numbers
    sorted_textual_nums = [key for value in sorted_nums for key, val in num_dict.items() if val == value]

    # Join the sorted textual numbers into a single string
    sorted_string = ' '.join(sorted_textual_nums)

    return sorted_string

